import {validateMessage} from './validation.js';

// @spec specs/hal-engine-conversation-list/spec.md#1
it('preserves valid list_sessions paging and rejects malformed limits and cursors', () => {
  const before = {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'};
  const valid = [
    {},
    {limit: 0},
    {limit: 201, before},
    {before: {sessionId: 'a'.repeat(128), updatedAt: 0}},
  ];
  const invalid = [
    {limit: -1},
    {limit: 1.5},
    {limit: '10'},
    {limit: null},
    {limit: Infinity},
    {before: null},
    {before: 'cursor'},
    {before: {}},
    {before: {...before, sessionId: ''}},
    {before: {...before, sessionId: 'a'.repeat(129)}},
    {before: {...before, updatedAt: 'not-a-date'}},
    {before: {...before, updatedAt: true}},
    {before: {...before, updatedAt: Infinity}},
  ];

  expect({
    accepted: valid.map(paging => validateMessage({type: 'list_sessions', ...paging, userId: 'other'})),
    rejected: invalid.map(paging => validateMessage({type: 'list_sessions', ...paging})),
  }).toEqual({
    accepted: valid.map(paging => ({valid: true, data: {type: 'list_sessions', ...paging}})),
    rejected: invalid.map(paging => ({valid: false, error: expect.stringContaining('limit' in paging ? 'limit' : 'before')})),
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/transport/ws/listSessionsPaging.test.ts --runInBand"

